use clap::Parser;
use log::LevelFilter;

#[derive(Parser, Debug)]
#[clap(name = "mdbook")]
#[clap(version = "mdbook v0.5.0-alpha.1")]
#[clap(about = "Creates a book from markdown files")]
#[clap(subcommand_required = false)]
enum Args {
    #[clap(about = "Creates the boilerplate structure and files for a new book")]
    Init(cli::InitArgs),

    #[clap(about = "Builds a book from its markdown files")]
    Build(cli::BuildArgs),

    #[clap(about = "Tests that a book's Rust code samples compile")]
    Test(cli::TestArgs),

    #[clap(about = "Deletes a built book")]
    Clean(cli::CleanArgs),

    #[clap(about = "Watches a book's files and rebuilds it on changes")]
    Watch(cli::WatchArgs),

    #[clap(about = "Serves a book at http://localhost:3000, and rebuilds it on changes")]
    Serve(cli::ServeArgs),

    #[clap(about = "Generate shell completions for your shell to stdout")]
    Completions(cli::CompletionsArgs),
}

fn main() {
    env_logger::builder()
        .filter_level(LevelFilter::Info)
        .format_timestamp_secs()
        .init();

    let args = Args::try_parse();

    match args {
        Ok(Args::Init(init_args)) => commands::init::execute(init_args),
        Ok(Args::Build(build_args)) => commands::build::execute(build_args),
        Ok(Args::Test(test_args)) => commands::test::execute(test_args),
        Ok(Args::Clean(clean_args)) => commands::clean::execute(clean_args),
        Ok(Args::Watch(watch_args)) => commands::watch::execute(watch_args),
        Ok(Args::Serve(serve_args)) => commands::serve::execute(serve_args),
        Ok(Args::Completions(comp_args)) => commands::completions::execute(comp_args),
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}
