cat > /workspace/src/main.rs << 'EOF'
use clap::{Parser, Subcommand};
use std::path::PathBuf;

mod init;
mod build;
mod clean;
mod watch;
mod serve;
mod test;
mod completions;

#[derive(Parser)]
#[clap(name = "mdbook")]
#[clap(version = "mdbook v0.5.0-alpha.1")]
#[clap(about = "Creates a book from markdown files")]
struct Cli {
    #[clap(subcommand)]
    command: Option<Command>,

    #[clap(short, long)]
    version: bool,
}

#[derive(Subcommand)]
enum Command {
    /// Creates the boilerplate structure and files for a new book
    Init {
        /// Directory to create the book in
        #[clap(default_value = ".")]
        dir: String,

        /// Copies the default theme into your source folder
        #[clap(long)]
        theme: bool,

        /// Skips confirmation prompts
        #[clap(long)]
        force: bool,

        /// Sets the book title
        #[clap(long)]
        title: Option<String>,

        /// Creates a VCS ignore file (i.e. .gitignore)
        #[clap(long)]
        ignore: Option<String>,
    },

    /// Builds a book from its markdown files
    Build {
        /// Root directory for the book
        #[clap(default_value = ".")]
        dir: String,

        /// Output directory for the book
        #[clap(short, long)]
        dest_dir: Option<String>,

        /// Opens the compiled book in a web browser
        #[clap(short)]
        open: bool,
    },

    /// Tests that a book's Rust code samples compile
    Test {
        /// Root directory for the book
        #[clap(default_value = ".")]
        dir: String,

        /// Output directory for the book
        #[clap(short, long)]
        dest_dir: Option<String>,

        /// Specific chapter to test
        #[clap(short)]
        chapter: Option<String>,

        /// Library search path for rustdoc
        #[clap(short = 'L', long)]
        library_path: Option<String>,
    },

    /// Deletes a built book
    Clean {
        /// Root directory for the book
        #[clap(default_value = ".")]
        dir: String,

        /// Output directory for the book
        #[clap(short, long)]
        dest_dir: Option<String>,
    },

    /// Watches a book's files and rebuilds it on changes
    Watch {
        /// Root directory for the book
        #[clap(default_value = ".")]
        dir: String,

        /// Output directory for the book
        #[clap(short, long)]
        dest_dir: Option<String>,

        /// Opens the compiled book in a web browser
        #[clap(short)]
        open: bool,

        /// The filesystem watching technique
        #[clap(long, default_value = "poll")]
        watcher: String,
    },

    /// Serves a book at http://localhost:3000, and rebuilds it on changes
    Serve {
        /// Root directory for the book
        #[clap(default_value = ".")]
        dir: String,

        /// Output directory for the book
        #[clap(short, long)]
        dest_dir: Option<String>,

        /// Hostname to listen on for HTTP connections
        #[clap(short, long, default_value = "localhost")]
        hostname: String,

        /// Port to use for HTTP connections
        #[clap(short, long, default_value = "3000")]
        port: u16,

        /// Opens the compiled book in a web browser
        #[clap(short)]
        open: bool,

        /// The filesystem watching technique
        #[clap(long, default_value = "poll")]
        watcher: String,
    },

    /// Generate shell completions for your shell to stdout
    Completions {
        /// The shell to generate completions for
        shell: String,
    },
}

fn main() {
    let cli = Cli::parse();

    if cli.version {
        println!("mdbook v0.5.0-alpha.1");
        return;
    }

    match cli.command {
        None => {
            eprintln!("Creates a book from markdown files\n");
            eprintln!("Usage: executable [COMMAND]\n");
            eprintln!("Commands:");
            eprintln!("  init         Creates the boilerplate structure and files for a new book");
            eprintln!("  build        Builds a book from its markdown files");
            eprintln!("  test         Tests that a book's Rust code samples compile");
            eprintln!("  clean        Deletes a built book");
            eprintln!("  completions  Generate shell completions for your shell to stdout");
            eprintln!("  watch        Watches a book's files and rebuilds it on changes");
            eprintln!("  serve        Serves a book at http://localhost:3000, and rebuilds it on changes");
            eprintln!("  help         Print this message or the help of the given subcommand(s)\n");
            eprintln!("Options:");
            eprintln!("  -h, --help     Print help");
            eprintln!("  -V, --version  Print version\n");
            eprintln!("For more information about a specific command, try `mdbook <command> --help`");
            eprintln!("The source code for mdBook is available at: https://github.com/rust-lang/mdBook");
        }
        Some(Command::Init { dir, theme, force, title, ignore }) => {
            init::execute(&dir, theme, force, title, ignore);
        }
        Some(Command::Build { dir, dest_dir, open }) => {
            build::execute(&dir, dest_dir, open);
        }
        Some(Command::Test { dir, dest_dir, chapter, library_path }) => {
            test::execute(&dir, dest_dir, chapter, library_path);
        }
        Some(Command::Clean { dir, dest_dir }) => {
            clean::execute(&dir, dest_dir);
        }
        Some(Command::Watch { dir, dest_dir, open, watcher }) => {
            watch::execute(&dir, dest_dir, open, &watcher);
        }
        Some(Command::Serve { dir, dest_dir, hostname, port, open, watcher }) => {
            serve::execute(&dir, dest_dir, &hostname, port, open, &watcher);
        }
        Some(Command::Completions { shell }) => {
            completions::execute(&shell);
        }
    }
}
EOF

