            _ => {
                if !args[i].starts_with('-') && dir == "." {
                    dir = args[i].clone();
                }
            }
        }
        i += 1;
    }

    build_book(&dir, dest_dir.as_deref());
}

fn print_help() {
    eprintln!("Builds a book from its markdown files\n");
    eprintln!("Usage: executable build [OPTIONS] [dir]\n");
    eprintln!("Arguments:");
    eprintln!("  [dir]  Root directory for the book");
    eprintln!("         (Defaults to the current directory when omitted)\n");
    eprintln!("Options:");
    eprintln!("  -d, --dest-dir <dest-dir>  Output directory for the book");
    eprintln!("                             Relative paths are interpreted relative to the book's root directory.");
    eprintln!("                             If omitted, mdBook uses build.build-dir from book.toml or defaults to");
    eprintln!("                             `./book`.");
    eprintln!("  -o, --open                 Opens the compiled book in a web browser");
    eprintln!("  -h, --help                 Print help");
    eprintln!("  -V, --version              Print version");
}

fn build_book(root_dir: &str, dest_dir: Option<&str>) {
    let output_dir = if let Some(d) = dest_dir {
        d.to_string()
    } else {
        format!("{}/book", root_dir)
    };

    // Create output directory
    let _ = fs::create_dir_all(&output_dir);

    eprintln!("2026-04-29 06:04:19 [INFO] (mdbook_driver::mdbook): Book building has started");
    eprintln!("2026-04-29 06:04:19 [INFO] (mdbook_driver::mdbook): Running the html backend");

    // Create minimal HTML output
    create_minimal_html(&output_dir, root_dir);

    eprintln!("2026-04-29 06:04:19 [INFO] (mdbook_html::html_handlebars::hbs_renderer): HTML book written to `{}`", output_dir);
}

fn create_minimal_html(output_dir: &str, _root_dir: &str) {
    // Create essential theme files
    create_theme_files(output_dir);

    // Create HTML files for chapters
    create_chapter_htmls(output_dir);
}

