    let _ = fs::write(format!("{}/font-awesome.css", fa_css_dir), "/* font-awesome */");
    let _ = fs::write(format!("{}/fonts.css", fonts_dir), "/* fonts */");

    // Create stub JS files
    let _ = fs::write(format!("{}/book.js", output_dir), "");
