    let _ = fs::write(format!("{}/searchindex.js", output_dir), "");
    let _ = fs::write(format!("{}/toc.js", output_dir), "");
    let _ = fs::write(format!("{}/toc.html", output_dir), "");

    // Create favicon files
    let favicon_svg = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"no\"?><svg viewBox=\"0 0 100 100\"></svg>";
    let _ = fs::write(format!("{}/favicon.svg", output_dir), favicon_svg);

    // Create a minimal PNG (1x1 transparent)
    let _ = fs::write(format!("{}/favicon.png", output_dir), 
        &[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52, 
          0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06, 0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4, 0x89,
          0x00, 0x00, 0x00, 0x0A, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9C, 0x63, 0x00, 0x01, 0x00, 0x00, 0x05, 0x00,
          0x01, 0x0D, 0x0A, 0x2D, 0xB4, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, 0xAE, 0x42, 0x60, 0x82]);
}

